public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack,
            @Nullable LivingEntity target, @Nullable BlockPos targetPos, @Nullable Vec3 hitVec, int chargedTicks) {
        super.perform(attacker, hand, item, itemStack, target, targetPos, hitVec, chargedTicks);

        boolean isDefensive = isDefensive(item, itemStack, hand);
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
        boolean overextended = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend) > 0;

        double exhaustDuration = item.getEffectEfficiency(itemStack, ItemEffect.overpower);

        if (!attacker.level().isClientSide && !isDefensive) {
            int currentAmp = Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);

            int newAmp = 1;

            if (overchargeBonus > 0) {
                newAmp += (int) (overchargeBonus * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));
            }

            double comboEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityCombo);
            if (comboEfficiency > 0 && attacker.getCommandSenderWorld().getRandom().nextFloat() < (comboEfficiency * ComboPoints.get(attacker) / 100f)) {
                newAmp--;

                RandomSource rand = attacker.getCommandSenderWorld().getRandom();
                ((ServerLevel) attacker.getCommandSenderWorld()).sendParticles(ParticleTypes.HAPPY_VILLAGER,
                        attacker.getX(), attacker.getY() + attacker.getBbHeight() / 2, attacker.getZ(), 10,
                        rand.nextGaussian() * 0.3, rand.nextGaussian() * attacker.getBbHeight() * 0.8, rand.nextGaussian() * 0.3, 0.1f);
            }

            if (target != null && revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                newAmp--;
            }

            if (overextended && !attacker.getFoodData().needsFood()) {
                newAmp = -1;
            }

            if (newAmp > 0) {
                int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
                if (echoLevel > 0) {
                    delayExhaustion(attacker, item, itemStack, (int) (exhaustDuration * 20), newAmp);
                } else {
                    attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, (int) (exhaustDuration * 20),
                            newAmp + currentAmp, false, true));
                }
            }
        }

        attacker.causeFoodExhaustion(overextended ? 6 : 1);
        attacker.swing(hand, false);

        int cooldown = getCooldown(item, itemStack);

        if (isDefensive) {
            cooldown = (int) (cooldown * (1 + item.getEffectEfficiency(itemStack, ItemEffect.abilityDefensive) / 100f));
        }

        if (ComboPoints.canSpend(item, itemStack)) {
            ComboPoints.reset(attacker);
        }

        if (target != null && revengeLevel > 0) {
            RevengeTracker.removeEnemy(attacker, target);
        }

        attacker.getCooldowns().addCooldown(item, cooldown);
    }

private void delayExhaustion(Player attacker, ItemModularHandheld item, ItemStack itemStack, int duration, int amplifier) {
        int delay = getChargeTime(item, itemStack) + getCooldown(item, itemStack) + item.getEffectLevel(itemStack, ItemEffect.abilityEcho);

        try {
            DelayData data = delayCache.get(attacker.getId(), DelayData::new);
            data.timestamp = attacker.level().getGameTime() + delay;
            data.amplifier += amplifier;
        } catch (ExecutionException e) {
            e.printStackTrace();
        }

        ServerScheduler.schedule(delay + 1, () -> {
            DelayData data = delayCache.getIfPresent(attacker.getId());
            if (attacker.isAlive() && attacker.level() != null && data != null && attacker.level().getGameTime() > data.timestamp) {
                int currentAmp = Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                        .map(MobEffectInstance::getAmplifier)
                        .orElse(-1);
                attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, duration, currentAmp + data.amplifier, false, true));

                delayCache.invalidate(attacker.getId());
            }
        });
    }

@SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }

        for (Iterator<Task> it = queue.iterator(); it.hasNext(); ) {
            Task task = it.next();
            if (task.getTick() < counter) {
                task.run();
                it.remove();
            }
        }

        counter++;
    }

@Override
	public void handleKeyInput() {
		if (getPlayer() instanceof ServerPlayer player) {
			if (!primedAttack && skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get()).hasAmount(this.energyCost)) {
				this.primedAttack = true;

				activatedActionKey(player);
			}
		}
	}

private void handleAfterAttacking(LivingDamageEvent.Post ev) {
		if (ev.getNewDamage() > 0 && primedAttack && DamageUtil.isMeleeDamage(ev.getSource()) && !getPlayer().getItemInHand(InteractionHand.OFF_HAND).isEmpty()) {
			this.primedAttack = false;

			if (skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get()).consume(this.energyCost, true)) {
				ServerPlayer player = (ServerPlayer)getPlayer();
				LivingEntity target = ev.getEntity();

				AoAScheduler.schedule(player.getCurrentSwingDuration() - 1, tick -> {
					player.swing(InteractionHand.OFF_HAND, true);

					if (target != null && target.isAlive()) {
						if (player.distanceToSqr(target) < 36 && player.hasLineOfSight(target)) {
							DamageUtil.doScaledKnockback(target, player, 0.3f, 1, 1, 1);
							EntityUtil.applyPotions(target, player, new EffectBuilder(MobEffects.MOVEMENT_SLOWDOWN, this.stunDuration).level(127), new EffectBuilder(MobEffects.DIG_SLOWDOWN, this.stunDuration).level(127));
							activatedActionKey(player);

							if (skill.canGainXp(true))
								PlayerUtil.giveTimeBasedXpToPlayer(player, this.skill.type(), 39,  false);
						}
					}
				});
			}
		}
	}

public boolean canUse() {
            if(vulture.getTarget() != null && vulture.shouldSwoop()) {
                vulture.setFlying(true);
                return true;
            }
            return false;
        }

public void tick() {
            if(vulture.isFlying()){
                vulture.setTackling(true);
            }else{
                vulture.setTackling(false);
            }
            if (vulture.getTarget() != null) {
                this.vulture.getMoveControl().setWantedPosition(vulture.getTarget().getX(), vulture.getTarget().getY() + vulture.getTarget().getEyeHeight(), vulture.getTarget().getZ(), 2.0D);
                final double d0 = this.vulture.getX() - this.vulture.getTarget().getX();
                final double d2 = this.vulture.getZ() - this.vulture.getTarget().getZ();
                final float f = (float)(Mth.atan2(d2, d0) * (double)Mth.RAD_TO_DEG) - 90.0F;
                vulture.setYRot(f);
                vulture.yBodyRot = vulture.getYRot();
                if (vulture.getBoundingBox().inflate(0.3F, 0.3F, 0.3F).intersects(vulture.getTarget().getBoundingBox()) && vulture.tackleCooldown == 0) {
                    tackleCooldown = 100 + random.nextInt(200);
                    float dmg = (float) vulture.getAttribute(Attributes.ATTACK_DAMAGE).getValue();
                    if(vulture.getTarget().hurt(vulture.damageSources().mobAttack(vulture), dmg)){
                        if(vulture.getHealth() < vulture.getMaxHealth() - dmg && vulture.getSoulLevel() < 5){
                            this.vulture.setSoulLevel(vulture.getSoulLevel() + 1);
                            this.vulture.heal(dmg);
                            this.vulture.level().broadcastEntityEvent(vulture, (byte)68);
                        }
                    }
                    stop();
                }
            }
        }

public void tick() {
        super.tick();
        this.prevTackleProgress = tackleProgress;
        this.prevFlyProgress = flyProgress;
        if (!this.level().isClientSide) {
            if(perchSearchCooldown > 0){
                perchSearchCooldown--;
            }
            if(this.getTarget() != null && this.getTarget().isAlive()){
                this.setPerchPos(this.getTarget().blockPosition().above(7));
            }else{
                if (this.getPerchPos() != null && !isPerchBlock(this.getPerchPos(), level().getBlockState(this.getPerchPos()))) {
                    this.setPerchPos(null);
                }
            }
            if (this.getPerchPos() == null && perchSearchCooldown == 0) {
                perchSearchCooldown = 20 + random.nextInt(20);
                this.setPerchPos(this.findNewPerchPos());
            }
            if (!isFlying() && landingCooldown == 0 && (this.getPerchPos() == null || this.shouldLeavePerch(this.getPerchPos()))) {
                this.setFlying(true);
            }
            if (!isFlying() && this.getTarget() != null){
                this.setFlying(true);
            }

            if(landingCooldown > 0 && isFlying() && this.onGround() && this.getTarget() == null){
                this.setFlying(false);
            }
        }
        final boolean flying = isFlying();
        if (flying) {
            if (this.isLandNavigator)
                switchNavigator(false);

            if (flyProgress < 5F)
                flyProgress++;
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);

            if (flyProgress > 0F)
                flyProgress--;
        }

        if (this.isTackling()) {
            if (tackleProgress < 5F)
                tackleProgress++;
        } else {
            if (tackleProgress > 0F)
                tackleProgress--;
        }

        if(landingCooldown > 0){
            landingCooldown--;
        }
        if(tackleCooldown > 0){
            tackleCooldown--;
        }
        if (isFlying()) {
            this.setNoGravity(true);
        } else {
            this.setNoGravity(false);
        }
        if (this.level().isClientSide  && hasSoulHeart()) {
            final float radius = 0.25F + random.nextFloat() * 1F;
            final float fly = this.flyProgress * 0.2F;
            final float wingSpread = 15F + 65 * fly + random.nextInt(5);
            final float angle = (Maths.STARTING_ANGLE * ((random.nextBoolean() ? -1 : 1) * (wingSpread + 180) + this.yBodyRot));
            final float angleMotion = (Maths.STARTING_ANGLE * this.yBodyRot);
            final double extraX = radius * Mth.sin(Mth.PI + angle);
            final double extraZ = radius * Mth.cos(angle);
            final double mov = this.getDeltaMovement().length();
            final double extraXMotion = -mov * Mth.sin((float) (Math.PI + angleMotion));
            final double extraZMotion = -mov * Mth.cos(angleMotion);
            final double yRandom = 0.2F + random.nextFloat() * 0.3F;
            this.level().addParticle(ParticleTypes.SOUL_FIRE_FLAME, this.getX() + extraX, this.getY() + yRandom, this.getZ() + extraZ, extraXMotion, random.nextFloat() * 0.1F, extraZMotion);
        }
    }

