public boolean canUse() {
            return  !vulture.shouldSwoop() && this.vulture.isFlying() && this.vulture.getPerchPos() != null;
        }

public void stop() {
            circlingTime = 0;
            speed = 0.8F + random.nextFloat() * 0.4F;
            yLevel = vulture.random.nextInt(3);
            maxCirclingTime = 360 + this.vulture.random.nextInt(80);
            circleDistance = 5 + this.vulture.random.nextFloat() * 5;
            clockwise = this.vulture.random.nextBoolean();
            this.vulture.tackleCooldown = 0;
        }

public void tick() {
            BlockPos encircle = vulture.getPerchPos();
            double localSpeed = speed;
            if(this.vulture.getTarget() != null){
                localSpeed *= 1.55D;
            }
            if (encircle != null) {
                circlingTime++;
                if(circlingTime > 360){
                    vulture.getMoveControl().setWantedPosition(encircle.getX() + 0.5D, encircle.getY() + 1.1D, encircle.getZ() + 0.5D, localSpeed);
                    if(vulture.verticalCollision || this.vulture.distanceToSqr(encircle.getX() + 0.5D, encircle.getY() + 1.1D, encircle.getZ() + 0.5D) < 1D){
                        vulture.setFlying(false);
                        vulture.setDeltaMovement(Vec3.ZERO);
                        vulture.landingCooldown = 400 + random.nextInt(1200);
                        stop();
                    }
                }else{
                    BlockPos circlePos = getVultureCirclePos(encircle);
                    if (circlePos != null) {
                        vulture.getMoveControl().setWantedPosition(circlePos.getX() + 0.5D, circlePos.getY() + 0.5D, circlePos.getZ() + 0.5D, localSpeed);
                    }
                }
            }
        }

public boolean doHurtTarget(Entity entityIn) {
        this.entityData.set(ATTACK_TICK, 5);
        return super.doHurtTarget(entityIn);
    }

public void tick() {
        super.tick();
        prevAttackProgress = attackProgress;
        if (this.entityData.get(ATTACK_TICK) > 0) {
            if(attackProgress == 3){
                this.playSound(AMSoundRegistry.LOBSTER_ATTACK.get(), this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.entityData.get(ATTACK_TICK) == 2 && this.getTarget() != null && this.distanceTo(this.getTarget()) < 1.3D) {
                this.getTarget().hurt(this.damageSources().mobAttack(this), 2);
            }
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        if(attackCooldown > 0){
            attackCooldown--;
        }
        if(this.getTarget() != null && this.distanceTo(this.getTarget()) <= 1F && attackCooldown == 0){
            this.lookAt(this.getTarget(), 180F, 20F);
            doHurtTarget(this.getTarget());
            attackCooldown = 20;
        }
    }

protected void explode(Vec3 position) {
		int count = 0;
		Entity shooter = getShooter();

		for (LivingEntity target : EntityRetrievalUtil.getEntities(this, 7, LivingEntity.class, target -> EntityUtil.areProbablyEnemies(target, shooter))) {
			if (DamageUtil.doMiscMagicAttack(shooter, target, getShotContext().damage(), position)) {
				HellfireProjectileEntity tail = new HellfireProjectileEntity(this, target.getX(), target.getY(), target.getZ());

				tail.setOwner(shooter);

				level().addFreshEntity(tail);
				target.igniteForSeconds(10);

				if (shooter != null)
					target.hurt(level().damageSources().indirectMagic(shooter, this), 0.1f);

				count++;
			}
		}

		level().playSound(null, getX(), getY(), getZ(), AoASounds.HELLFIRE_IMPACT.get(), getShooter() != null ? getShooter().getSoundSource() : SoundSource.PLAYERS, 1, 1);

		if (count >= 20 && shooter instanceof ServerPlayer)
			AdvancementUtil.grantCriterion((ServerPlayer)shooter, AdventOfAscension.id("overworld/heckfire"), "20_target_hellfire");
	}

public static boolean doMiscMagicAttack(@Nullable Entity attacker, Entity target, float dmg, @Nullable Vec3 position) {
		return safelyDealDamage(position == null ? attacker == null ?
												   miscDamage(AoADamageTypes.MAGIC_ATTACK, target.level()) :
												   entityDamage(AoADamageTypes.MAGIC_ATTACK, attacker) :
								positionedEntityDamage(AoADamageTypes.MAGIC_ATTACK, attacker, position), target, dmg);
	}

public static DamageSource miscDamage(ResourceKey<DamageType> damageType, Level level) {
		return new DamageSource(level.damageSources().damageTypes.getHolderOrThrow(damageType));
	}

public static DamageSource entityDamage(ResourceKey<DamageType> damageType, @NotNull Entity attacker) {
		return new DamageSource(attacker.level().damageSources().damageTypes.getHolderOrThrow(damageType), attacker);
	}

public static DamageSource positionedEntityDamage(ResourceKey<DamageType> damageType, @Nullable Entity attacker, Vec3 position) {
		return new DamageSource(RegistryUtil.getDataDrivenRegistry(Registries.DAMAGE_TYPE).getHolderOrThrow(damageType), attacker, attacker, position);
	}

public static boolean safelyDealDamage(DamageSource damageSource, Entity target, float dmg) {
		return safelyDealDamage(damageSource, target, dmg, true);
	}

public static boolean safelyDealDamage(DamageSource damageSource, Entity target, float dmg, boolean ignoreMiscEntities) {
		if (!ignoreMiscEntities && !(target instanceof LivingEntity) && !(target instanceof PartEntity<?>) && !(target instanceof EndCrystal))
			return false;

		if (target.hurt(damageSource, dmg)) {
			if (damageSource.getEntity() instanceof LivingEntity attacker)
				attacker.setLastHurtMob(target);

			return true;
		}

		return false;
	}

